package com.example.riskplatform.controller;import com.example.riskplatform.common.ApiResponse;import com.example.riskplatform.dto.Requests.MetricRequest;import com.example.riskplatform.entity.Metric;import com.example.riskplatform.service.MetricService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;@RestController @RequestMapping("/api/metrics") @RequiredArgsConstructor public class MetricController{private final MetricService s;@GetMapping @PreAuthorize("hasAuthority('metric:read')")public ApiResponse<List<Metric>>list(@RequestParam(required=false)Long companyId,@RequestParam(required=false)String metricCode,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate start,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate end){return ApiResponse.ok(s.list(companyId,metricCode,start,end));}@PostMapping @PreAuthorize("hasAuthority('metric:write')")public ApiResponse<Metric>create(@Valid @RequestBody MetricRequest r){return ApiResponse.ok(s.create(r));}}